<script setup lang="ts">
import type {SceneObject,Scene,Course} from '../player/model'
import {computed} from 'vue'
const props=defineProps<{object:SceneObject;scene:Scene;course:Course}>(),emit=defineEmits<{change:[o:SceneObject]}>()
const o=computed(()=>props.object)
function set(path:string,value:unknown){const copy=JSON.parse(JSON.stringify(o.value));const keys=path.split('.');let parent=copy;for(const k of keys.slice(0,-1))parent=parent[k];parent[keys.at(-1)!]=value;emit('change',copy)}
function input(e:Event){return (e.target as HTMLInputElement).value}
function number(path:string,e:Event){set(path,Number(input(e)))}
function addRow(group:'states'|'details'){const copy=JSON.parse(JSON.stringify(o.value));const target=group==='details'?copy.details:(copy.content.states??={});let n=1;while(target['新字段'+n]!==undefined)n++;target['新字段'+n]='内容';emit('change',copy)}
function rename(group:'states'|'details',old:string,key:string){if(!key||key===old)return;const copy=JSON.parse(JSON.stringify(o.value)),target=group==='details'?copy.details:copy.content.states;if(key in target)return;target[key]=target[old];delete target[old];emit('change',copy)}
function rowValue(group:'states'|'details',key:string,value:string){const copy=JSON.parse(JSON.stringify(o.value));(group==='details'?copy.details:copy.content.states)[key]=value;emit('change',copy)}
function flags(e:Event){const copy=JSON.parse(JSON.stringify(o.value));copy.content.packet.flags=input(e);if(input(e).includes('ACK'))copy.content.packet.ack??=0;emit('change',copy)}
function remove(group:'states'|'details',key:string){const copy=JSON.parse(JSON.stringify(o.value));delete (group==='details'?copy.details:copy.content.states)[key];emit('change',copy)}
function network(e:Event){const copy=JSON.parse(JSON.stringify(o.value));if((e.target as HTMLInputElement).checked)copy.content.packet={source:props.scene.objects.find(x=>x.type==='node'&&x.content.visual&&x.content.address)?.id||'',target:props.scene.objects.filter(x=>x.type==='node'&&x.content.visual&&x.content.address)[1]?.id||'',protocol:'TCP',sourcePort:1024,targetPort:80,flags:'SYN',seq:0,bytes:20};else delete copy.content.packet;emit('change',copy)}
function visual(e:Event){const copy=JSON.parse(JSON.stringify(o.value));if(input(e)){copy.content.visual=input(e);copy.content.address||='127.0.0.1'}else{delete copy.content.visual;delete copy.content.address}emit('change',copy)}
</script>
<template><div class="properties"><h3>对象属性</h3><small>{{o.type}} · {{o.id}}</small><label>对象名称<input aria-label="对象名称" :value="o.content.label" @input="set('content.label',input($event))"></label>
<div class="pair"><label v-for="k in ['x','y']">{{k.toUpperCase()}}<input :aria-label="'对象 '+k.toUpperCase()" type="number" min="-100000" max="100000" :value="o.position[k as 'x'|'y']" @input="number('position.'+k,$event)"></label><label v-for="k in ['width','height']">{{k==='width'?'宽度':'高度'}}<input :aria-label="k==='width'?'对象宽度':'对象高度'" type="number" min="1" max="100000" :value="o.size[k as 'width'|'height']" @input="number('size.'+k,$event)"></label></div>
<label><input type="checkbox" aria-label="初始可见" :checked="o.initial.visible" @change="set('initial.visible',($event.target as HTMLInputElement).checked)"> 初始可见</label><label><input type="checkbox" aria-label="初始高亮" :checked="o.initial.highlight" @change="set('initial.highlight',($event.target as HTMLInputElement).checked)"> 初始高亮</label><label>初始状态<input aria-label="初始状态" :value="o.initial.status" @input="set('initial.status',input($event))"></label>
<template v-if="o.type==='node'"><label>设备外观<select aria-label="设备外观" :value="o.content.visual||''" @change="visual"><option value="">通用流程节点</option><option v-for="v in ['laptop','server','router','cloud']" :value="v">{{v}}</option></select></label><label v-if="o.content.visual">设备地址<input aria-label="设备地址" :value="o.content.address" @input="set('content.address',input($event))"></label></template>
<template v-if="o.type==='edge'"><label v-for="k in ['source','target']">{{k==='source'?'连线起点':'连线终点'}}<select :aria-label="k==='source'?'连线起点':'连线终点'" :value="o.content[k as 'source'|'target']" @change="set('content.'+k,input($event))"><option v-for="n in scene.objects.filter(x=>x.type!=='edge')" :value="n.id">{{n.content.label}}</option></select></label></template>
<template v-if="o.type==='formula'"><label>公式 TeX<textarea aria-label="公式 TeX" :value="o.content.tex" @input="set('content.tex',input($event))"/></label><h4>按状态显示公式</h4><div v-for="(v,k) in o.content.states" class="row"><input aria-label="公式状态名" :value="k" @change="rename('states',String(k),input($event))"><input aria-label="状态公式" :value="v" @input="rowValue('states',String(k),input($event))"><button @click="remove('states',String(k))">移除</button></div><button @click="addRow('states')">添加状态公式</button></template>
<template v-if="o.type==='geometry'"><h4>几何顶点（对象内坐标）</h4><div v-for="(p,i) in o.content.points" class="row"><input v-for="k in ['x','y']" :aria-label="'顶点 '+i+' '+k" type="number" :value="p[k as 'x'|'y']" @input="number('content.points.'+i+'.'+k,$event)"><button :disabled="o.content.points!.length<=3" @click="set('content.points',o.content.points!.filter((_,j)=>i!==j))">移除点</button></div><button @click="set('content.points',[...o.content.points!,{x:50,y:50}])">添加顶点</button></template>
<label v-if="o.type==='image'">图片资源<select aria-label="图片资源" :value="o.content.assetId" @change="set('content.assetId',input($event))"><option v-for="a in course.assets" :value="a.id">{{a.purpose}} · {{a.id}}</option></select></label>
<template v-if="o.type==='packet'"><label><input type="checkbox" aria-label="TCP字段" :checked="!!o.content.packet" @change="network"> TCP 报文字段</label><template v-if="o.content.packet"><label v-for="k in ['source','target']">{{k==='source'?'报文源设备':'报文目标设备'}}<select :aria-label="'报文 '+k" :value="o.content.packet[k as 'source'|'target']" @change="set('content.packet.'+k,input($event))"><option v-for="n in scene.objects.filter(x=>x.type==='node'&&x.content.visual&&x.content.address)" :value="n.id">{{n.content.label}}</option></select></label><label>标志<select aria-label="报文标志" :value="o.content.packet.flags" @change="flags"><option>SYN</option><option>SYN, ACK</option><option>ACK</option></select></label><label v-for="k in ['sourcePort','targetPort','seq','ack','bytes']">{{k}}<input :aria-label="'报文 '+k" type="number" :value="(o.content.packet as any)[k]" @input="number('content.packet.'+k,$event)"></label></template></template>
<h4>详情字段</h4><div v-for="(v,k) in o.details" class="row"><input aria-label="详情字段名" :value="k" @change="rename('details',String(k),input($event))"><input aria-label="详情内容" :value="v" @input="rowValue('details',String(k),input($event))"><button @click="remove('details',String(k))">移除</button></div><button @click="addRow('details')">添加详情字段</button></div></template>
<style scoped>.properties{padding:12px;background:#f7f9f7;border:1px solid #dae4dd;border-radius:8px;max-height:850px;overflow:auto}.properties h3{margin:0 0 8px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:8px}.row{display:flex;gap:4px;margin-bottom:6px}.row input{min-width:0;width:40%}.properties input[type=checkbox]{width:auto;display:inline}.properties textarea{min-height:70px}.properties h4{margin:18px 0 8px}</style>
